{
  "name": "ScanOrder",
  "description": "Starter: the lamp rung is above the rung that sets ButtonSeen, so the lamp follows one scan late.",
  "version": "1.0.0",
  "variables": {
    "local": [
      {
        "name": "ButtonSeen",
        "type": "BOOL",
        "initialValue": false,
        "comment": "Remembers, inside the program, that the button is pressed"
      }
    ],
    "inputs": [
      {
        "name": "StartButton",
        "type": "BOOL",
        "address": "%I0.0",
        "comment": "Start pushbutton, normally open: TRUE while pressed"
      }
    ],
    "outputs": [
      {
        "name": "Lamp",
        "type": "BOOL",
        "address": "%Q0.0",
        "comment": "Lamp: TRUE lights it"
      }
    ]
  },
  "rungs": [
    {
      "id": "rung_1",
      "number": 1,
      "comment": "Show ButtonSeen on the lamp. This rung runs before ButtonSeen is updated: move the other rung above it.",
      "branches": [],
      "gridConfig": {
        "cols": 8,
        "rows": 1,
        "cellWidth": 80,
        "cellHeight": 60
      },
      "grid": [
        [
          {
            "element": {
              "id": "e0_0_1",
              "type": "contact_no",
              "variable": "ButtonSeen",
              "row": 0,
              "col": 0
            },
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": null,
            "hasWire": true
          },
          {
            "element": {
              "id": "e0_7_1",
              "type": "coil",
              "variable": "Lamp",
              "row": 0,
              "col": 7
            },
            "hasWire": true
          }
        ]
      ]
    },
    {
      "id": "rung_2",
      "number": 2,
      "comment": "Copy the button into ButtonSeen.",
      "branches": [],
      "gridConfig": {
        "cols": 8,
        "rows": 1,
        "cellWidth": 80,
        "cellHeight": 60
      },
      "grid": [
        [
          {
            "element": {
              "id": "e0_0_2",
              "type": "contact_no",
              "variable": "StartButton",
